/* Encoder for /app/decomp.c
 *
 * decomp.c is an adaptive arithmetic (range) decoder + LZ77 decoder:
 *   - j = get_integer(9,0)  number of operations
 *   - each op: bit(ctx1); if 1: offset=get_integer(5,2), len=get_integer(2,3)+1, copy
 *              if 0: sign=get_bit(8), val=get_integer(4,9), byte=(1-2*sign)*val
 *
 * get_integer(t,c): ctx99=c*99; escapes get_bit(t+k+ctx99) until a 1 (k>=1),
 *   then (t+k-1) data bits get_bit(ctx99); value = 2^(t+k-1)+data - 2^t.
 *
 * The arithmetic core (radix 255):
 *   if(range<255){range*=255; fraction*=255; fraction+=byte-1;}
 *   split = range*(c0+1)/(c0+c1+2); b = fraction>=split;
 *   fraction-=split*b; range = b?range-split:split; c[b]++;
 *
 * This file mirrors that exactly to produce the byte stream.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static unsigned char *data;
static int ndata;

/* ---------------- bit-count helpers (raw cost model) ---------------- */
static int litbits(int v){
  if(v<16) return 5;
  if(v<32) return 7;
  if(v<64) return 9;
  if(v<128) return 11;
  return 13;
}
static int offbits(int x){ /* x = off-1, t=5 */
  if(x<32) return 6;
  if(x<64) return 8;
  if(x<128) return 10;
  if(x<256) return 12;
  if(x<512) return 14;
  if(x<1024) return 16;
  if(x<2048) return 18;
  if(x<4096) return 20;
  if(x<8192) return 22;
  return 24;
}
static int lenbits(int y){ /* y = len-1, t=2 */
  if(y<4) return 3;
  if(y<8) return 5;
  if(y<16) return 7;
  if(y<32) return 9;
  if(y<64) return 11;
  if(y<128) return 13;
  if(y<256) return 15;
  if(y<512) return 17;
  if(y<1024) return 19;
  if(y<2048) return 21;
  if(y<4096) return 23;
  if(y<8192) return 25;
  return 27;
}
static int jbits(int v){ /* get_integer(9,0) */
  if(v<512) return 10;
  if(v<1024) return 12;
  if(v<2048) return 14;
  if(v<4096) return 16;
  if(v<8192) return 18;
  return 20;
}

/* ---------------- LZ77 ---------------- */
typedef struct { int is_copy; int off; int len; int val; } Op;
#define MAXOPS 20000
static Op ops[MAXOPS];
static int nop;

static int head[65536];
static int prevpos[12000];

/* reward per saved byte beyond the first two of a match, in "raw bits" */
#ifndef MATCH_REWARD
#define MATCH_REWARD 5
#endif
#ifndef MINMATCH
#define MINMATCH 2
#endif

static void lz77(void){
  int i, p, k, m, L, d, c, considered;
  int bestcost, besttype, bestoff, bestlen, maxlen;
  memset(head, -1, sizeof(head));
  nop = 0;
  i = 0;
  if(i+1 < ndata){ int key = data[i]*256 + data[i+1]; prevpos[i] = head[key]; head[key] = i; }
  while (i < ndata){
    int v = data[i];
    bestcost = 2 + litbits(v);
    besttype = 0; bestoff = 0; bestlen = 1;
    if (i+1 < ndata){
      int key = data[i]*256 + data[i+1];
      p = head[key];
      considered = 0;
      maxlen = ndata - i; if (maxlen > 9999) maxlen = 9999;
      while (p >= 0 && considered < 64){
        d = i - p;
        if (d >= 1 && d <= 9999){
          m = 0;
          while (m < maxlen && data[p+m] == data[i+m]) m++;
          if (m >= MINMATCH){
            /* evaluate a handful of lengths: full, and a few truncations */
            for (k = 0; k < 5; k++){
              if (k==0) L = m;
              else if (k==1) L = m-1;
              else if (k==2) L = m/2;
              else if (k==3) L = m/4;
              else L = 2;
              if (L < MINMATCH || L > m) continue;
              c = 1 + offbits(d-1) + lenbits(L-1) - (L-2)*MATCH_REWARD;
              if (c < bestcost){
                bestcost = c; besttype = 1; bestoff = d; bestlen = L;
              }
            }
          }
        }
        p = prevpos[p];
        considered++;
      }
    }
    if (besttype == 1){
      ops[nop].is_copy = 1; ops[nop].off = bestoff; ops[nop].len = bestlen;
      i += bestlen;
    } else {
      ops[nop].is_copy = 0; ops[nop].val = v;
      i += 1;
    }
    nop++;
    if (i+1 < ndata){
      int key = data[i]*256 + data[i+1];
      prevpos[i] = head[key]; head[key] = i;
    }
  }
}

/* ---------------- arithmetic encoder ---------------- */
static long erange = 1;
static long efrac = 0;
static int ec0[4096], ec1[4096];
static unsigned char outbytes[8192];
static int outlen = 0;
static int enc_fail = 0;

static int eenc_bit(int ctx, int bit){
  long split, lo_ach, hi_ach, dlo, dhi, vlo, vhi, target, d;
  if (erange < 255){
    erange *= 255;
    split = erange * (ec0[ctx]+1) / (ec0[ctx]+ec1[ctx]+2);
    lo_ach = 255*efrac; hi_ach = 255*efrac + 254;
    if (bit){ dlo = split - lo_ach; if (dlo < 0) dlo = 0; dhi = 254; }
    else { dlo = 0; dhi = split - lo_ach - 1; if (dhi > 254) dhi = 254; }
    if (dlo > dhi){ enc_fail = 1; return -1; }
    vlo = bit ? split : 0; vhi = bit ? erange : split;
    target = (vlo+vhi)/2;
    if (target < lo_ach) target = lo_ach;
    if (target > hi_ach) target = hi_ach;
    if (target < vlo || target >= vhi){ enc_fail = 1; return -1; }
    d = target - lo_ach;
    efrac = 255*efrac + d;
    outbytes[outlen++] = (unsigned char)(d+1);
  }
  split = erange * (ec0[ctx]+1) / (ec0[ctx]+ec1[ctx]+2);
  {
    int actual = (efrac >= split) ? 1 : 0;
    if (actual != bit){ enc_fail = 1; return -1; }
    efrac -= split*bit;
    erange = bit ? erange-split : split;
    if (bit) ec1[ctx]++; else ec0[ctx]++;
  }
  return 0;
}

static int emit_get_integer(int t, int c, int v){
  int ctx99 = c*99;
  int k = 1;
  long hi = (1L<<t) - 1;
  long data;
  int nd, e, b, ctx;
  while (v > hi){ k++; hi = (1L<<t)*(1L<<k) - 1; }
  for (e = 0; e < k-1; e++){
    ctx = t + (e+1) + ctx99;
    if (eenc_bit(ctx, 0)) return -1;
  }
  ctx = t + k + ctx99;
  if (eenc_bit(ctx, 1)) return -1;
  nd = t + k - 1;
  data = v - (1L<<t)*((1L<<(k-1)) - 1);
  for (b = 0; b < nd; b++){
    int bit = (int)((data >> (nd-1-b)) & 1);
    if (eenc_bit(ctx99, bit)) return -1;
  }
  return 0;
}

static int encode_ops(void){
  int i;
  erange = 1; efrac = 0; memset(ec0, 0, sizeof(ec0)); memset(ec1, 0, sizeof(ec1));
  outlen = 0; enc_fail = 0;
  if (emit_get_integer(9, 0, nop)) return -1;
  for (i = 0; i < nop; i++){
    if (ops[i].is_copy){
      if (eenc_bit(1, 1)) return -1;
      if (emit_get_integer(5, 2, ops[i].off-1)) return -1;
      if (emit_get_integer(2, 3, ops[i].len-1)) return -1;
    } else {
      if (eenc_bit(1, 0)) return -1;
      if (eenc_bit(8, 0)) return -1;
      if (emit_get_integer(4, 9, ops[i].val)) return -1;
    }
  }
  if (enc_fail) return -1;
  return 0;
}

/* ---------------- self-check: faithful mirror of decomp.c ---------------- */
static int radix = 255;
static long drange = 1;
static int dfraction;
static int dcc[1000000];
static const unsigned char *inbuf;
static int inlen, inpos;
static int din_eof = 0;

static int dgc(void){
  if (inpos >= inlen){ din_eof = 1; return -1; }
  return (int)inbuf[inpos++];
}
static int dget_bit(int ctx){
  if (drange < radix){
    drange *= radix;
    dfraction *= radix;
    dfraction += dgc()-1;
  }
  int *counts = dcc + ctx*2;
  int split = drange * -~*counts / (*counts + counts[1] + 2);
  int the_bit = dfraction >= split;
  dfraction -= split*the_bit;
  drange = the_bit ? drange-split : split;
  counts[the_bit]++;
  return the_bit;
}
static int dget_integer(int tmp, int ctx){
  int subtract_it = 1<<tmp;
  int result_ans = 1;
  int i;
  ctx*=99;
  while (!dget_bit(++tmp+ctx));
  tmp--;
  for (i=0;i<tmp;i++) result_ans = result_ans*2 | dget_bit(ctx);
  return result_ans - subtract_it;
}

static int selfcheck(void){
  char buf[10000];
  char *Q = buf, *z;
  int j, tmp, ok = 1;
  drange = 1; dfraction = 0; memset(dcc, 0, sizeof(dcc));
  inpos = 0; inlen = outlen; inbuf = outbytes; din_eof = 0;
  j = dget_integer(9, 0);
  while (j--){
    if (dget_bit(1)){
      z = Q - dget_integer(5, 2) - 1;
      tmp = dget_integer(2, 3) + 1;
      { int i; for (i=0;i<tmp;i++) *Q++ = *z++; }
    } else {
      *Q++ = (1-2*dget_bit(8)) * dget_integer(4, 9);
    }
  }
  {
    int outn = (int)(Q - buf);
    if (outn != ndata){ fprintf(stderr, "selfcheck: length %d != %d\n", outn, ndata); ok = 0; }
    else if (memcmp(buf, data, ndata) != 0){ fprintf(stderr, "selfcheck: content mismatch\n"); ok = 0; }
    if (din_eof == 0 && inpos < inlen) fprintf(stderr, "note: %d trailing bytes unconsumed\n", inlen - inpos);
  }
  return ok;
}

/* ---------------- main ---------------- */
