/* Arithmetic encoder with backtracking, mirroring /app/decomp.c exactly.
 *
 * Decoder (decomp.c):
 *   if(range<255){range*=255; fraction*=255; fraction+=byte-1;}
 *   split = range*(c0+1)/(c0+c1+2); b = fraction>=split;
 *   fraction -= split*b; range = b?range-split:split; c[b]++;
 *
 * We are given the exact intended bit stream (ctx[i], bit[i]). The per-context
 * counts before each bit are fully determined by that bit stream (the decoder
 * has decoded exactly those bits so far), so we precompute them. The range
 * evolution is also bit-determined. Only the digits d (bytes-1) are our choice,
 * made at refill points (range<255). We DFS over digit choices with backtracking.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static int *cctx;    /* context per bit */
static int *cbit;    /* intended bit per bit */
static int N;        /* number of bits */

/* prefix counts per bit position (for that position's context) */
static int *pc0, *pc1;
/* decoder range evolution */
static char *isref;  /* 1 if a refill happens before bit i */
static long *cW;     /* relative width before the split at bit i (post-refill) */
static long *cS;     /* split at bit i */
/* run boundaries + lookahead valid interval (post-refill units, double) */
static int *runend;  /* last bit index of the run starting at i (only for run starts) */
static double *La, *Lw;

static void precompute(void){
  static int tmpc0[4096], tmpc1[4096];
  long W = 1;
  int i, j;
  memset(tmpc0,0,sizeof(tmpc0)); memset(tmpc1,0,sizeof(tmpc1));
  for (i=0;i<N;i++){
    if (W < 255){ isref[i]=1; W *= 255; } else isref[i]=0;
    cW[i] = W;
    pc0[i] = tmpc0[cctx[i]];
    pc1[i] = tmpc1[cctx[i]];
    cS[i] = W * (pc0[i]+1) / (pc0[i]+pc1[i]+2);
    if (cbit[i]) W = W - cS[i]; else W = cS[i];
    if (cbit[i]) tmpc1[cctx[i]]++; else tmpc0[cctx[i]]++;
  }
  /* runs: start at each i with isref[i]; run continues until next isref */
  i = 0;
  while (i < N){
    /* i should be a run start */
    j = i+1;
    while (j < N && !isref[j]) j++;
    runend[i] = j-1;
    i = j;
  }
  /* lookahead valid interval for each run, in post-refill units (double) */
  for (i=0;i<N;i++){
    if (!isref[i]) continue;
    double a = 0.0, w = (double)cW[i];
    int k;
    for (k=i;k<=runend[i];k++){
      double ratio = (double)(pc0[k]+1)/(double)(pc0[k]+pc1[k]+2);
      double S = w * ratio;
      if (cbit[k]){ a += S; w -= S; } else { w = S; }
    }
    La[i] = a; Lw[i] = w;
  }
}

/* ---------------- backtracking encoder ---------------- */
typedef struct {
  long i;        /* run-start bit index */
  long frac;     /* pre-refill fraction */
  long outlen;   /* output length at this point */
  long dlo, dhi; /* exact feasible digit range (first bit of run) */
  int  n;        /* number of candidates */
  int  idx;      /* next candidate index */
  int  cand[256];
} Ckpt;

static Ckpt stack[8192];
static int sp = 0;

static unsigned char outbytes[16384];
static int outlen = 0;
static long efrac = 0;

/* build candidate list sorted by |d - ideal| */
static void build_cands(Ckpt *cp, double ideal){
  long d;
  int n = 0;
  for (d = cp->dlo; d <= cp->dhi; d++){
    cp->cand[n++] = (int)d;
  }
  cp->n = n;
  /* simple selection sort by |d - ideal| (n <= 255) */
  {
    int x, y, bd;
    for (x=0;x<n;x++){
      bd = x;
      for (y=x+1;y<n;y++){
        if (fabs((double)cp->cand[y]-ideal) < fabs((double)cp->cand[bd]-ideal)) bd = y;
      }
      if (bd != x){ int t = cp->cand[x]; cp->cand[x] = cp->cand[bd]; cp->cand[bd] = t; }
    }
  }
  cp->idx = 0;
}

/* returns 0 on success, -1 if no encoding exists */
static int encode(void){
  long i = 0;
  efrac = 0;
  outlen = 0;
  sp = 0;
  while (1){
    while (i < N){
      if (isref[i]){
        Ckpt *cp = &stack[sp];
        long dlo, dhi, f255;
        double ideal;
        /* exact feasible range from the first bit of the run */
        f255 = 255 * efrac;
        if (cbit[i]){
          dlo = cS[i] - f255; if (dlo < 0) dlo = 0;
          dhi = 254;
        } else {
          dlo = 0;
          dhi = cS[i] - f255 - 1; if (dhi > 254) dhi = 254;
        }
        if (dlo > dhi) goto fail;
        cp->i = i; cp->frac = efrac; cp->outlen = outlen;
        cp->dlo = dlo; cp->dhi = dhi;
        ideal = (La[i] + Lw[i]/2.0) - f255;
        build_cands(cp, ideal);
        {
          int d = cp->cand[cp->idx++];
          efrac = 255*efrac + d;
          outbytes[outlen++] = (unsigned char)(d+1);
        }
        sp++;
        i++;
      } else {
        int actual = (efrac >= cS[i]) ? 1 : 0;
        if (actual != cbit[i]) goto fail;
        efrac -= cS[i] * cbit[i];
        i++;
      }
    }
    return 0; /* success */
fail:
    if (sp == 0) return -1;
    /* backtrack: pop until we find a checkpoint with a spare candidate */
    while (sp > 0){
      Ckpt *cp = &stack[sp-1];
      if (cp->idx < cp->n){
        int d = cp->cand[cp->idx++];
        efrac = cp->frac;
        outlen = cp->outlen;
        i = cp->i;
        efrac = 255*efrac + d;
        outbytes[outlen++] = (unsigned char)(d+1);
        i++;
        break;
      }
      sp--;
    }
    if (sp == 0) return -1;
  }
}

/* Encoder for /app/decomp.c  ->  produces /app/data.comp
 *
 * decomp.c: adaptive arithmetic (range, radix 255) + LZ77 decoder.
