#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static unsigned char *data;
static int ndata;

/* ---------- raw-bit cost helpers (for LZ77) ---------- */
static int litbits(int v){ if(v<16)return 5; if(v<32)return 7; if(v<64)return 9; if(v<128)return 11; return 13; }
static int offbits(int x){ if(x<32)return 6; if(x<64)return 8; if(x<128)return 10; if(x<256)return 12; if(x<512)return 14; if(x<1024)return 16; if(x<2048)return 18; if(x<4096)return 20; if(x<8192)return 22; return 24; }
static int lenbits(int y){ if(y<4)return 3; if(y<8)return 5; if(y<16)return 7; if(y<32)return 9; if(y<64)return 11; if(y<128)return 13; if(y<256)return 15; if(y<512)return 17; if(y<1024)return 19; if(y<2048)return 21; if(y<4096)return 23; if(y<8192)return 25; return 27; }
static int jbits(int v){ if(v<512)return 10; if(v<1024)return 12; if(v<2048)return 14; if(v<4096)return 16; if(v<8192)return 18; return 20; }

/* ---------- LZ77 ---------- */
typedef struct { int is_copy; int off; int len; int val; } Op;
#define MAXOPS 20000
static Op ops[MAXOPS];
static int nop;
static int head[65536];
static int prevpos[12000];

#ifndef MATCH_REWARD
#define MATCH_REWARD 5
#endif
#ifndef MINMATCH
#define MINMATCH 2
#endif
#ifndef MAXCAND
#define MAXCAND 64
#endif

static void lz77(void){
  int i, p, k, m, L, d, c, considered, maxlen, v;
  int bestcost, besttype, bestoff, bestlen;
  memset(head, -1, sizeof(head));
  nop = 0; i = 0;
  if (i+1 < ndata){ int key=data[i]*256+data[i+1]; prevpos[i]=head[key]; head[key]=i; }
  while (i < ndata){
    bestcost = 2 + litbits(data[i]);
    besttype = 0; bestoff = 0; bestlen = 1;
    if (i+1 < ndata){
      int key = data[i]*256 + data[i+1];
      p = head[key]; considered = 0;
      maxlen = ndata - i; if (maxlen > 9999) maxlen = 9999;
      while (p >= 0 && considered < MAXCAND){
        d = i - p;
        if (d >= 1 && d <= 9999){
          m = 0;
          while (m < maxlen && data[p+m] == data[i+m]) m++;
          if (m >= MINMATCH){
            for (k = 0; k < 5; k++){
              if (k==0) L = m; else if (k==1) L = m-1; else if (k==2) L = m/2; else if (k==3) L = m/4; else L = 2;
