/* Encoder for /app/decomp.c  ->  produces /app/data.comp
 *
 * decomp.c: adaptive arithmetic (range, radix 255) + LZ77 decoder.
 *   j = get_integer(9,0); then j ops:
 *     bit1==1: off=get_integer(5,2), len=get_integer(2,3)+1, copy
 *     bit1==0: sign=get_bit(8), val=get_integer(4,9), byte=(1-2*sign)*val
 *   get_integer(t,c): ctx99=c*99; escapes get_bit(t+k+ctx99) until 1 (k>=1),
 *     then (t+k-1) data bits get_bit(ctx99); value=2^(t+k-1)+data-2^t.
 *   get_bit: if(range<255){range*=255;fraction*=255;fraction+=byte-1;}
 *     split=range*(c0+1)/(c0+c1+2); b=fraction>=split;
 *     fraction-=split*b; range=b?range-split:split; c[b]++;
 *
 * The intended bit stream is known => per-context counts and the range
 * evolution are precomputed. Only the radix-255 digits at refill points are
 * free. We pick them with a 2-level lookahead (choose d to best position the
 * next run) + DFS backtracking as a safety net.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static unsigned char *data;
static int ndata;

/* ---------- raw-bit cost helpers (for LZ77) ----------
 * For get_integer(t,c): level K (K escapes) spans
 *   [ 2^t*(2^{K-1}-1) , 2^(t+K) - 2^t - 1 ]  and costs 2K+t-1 bits.          */
static int litbits(int v){ if(v<16)return 5; if(v<48)return 7; if(v<112)return 9; if(v<240)return 11; return 13; }
static int offbits(int x){ if(x<32)return 6; if(x<96)return 8; if(x<192)return 10; if(x<384)return 12; if(x<768)return 14; if(x<1536)return 16; if(x<3072)return 18; if(x<6144)return 20; if(x<12288)return 22; return 24; }
static int lenbits(int y){ if(y<6)return 3; if(y<12)return 5; if(y<28)return 7; if(y<60)return 9; if(y<124)return 11; if(y<252)return 13; if(y<508)return 15; if(y<1020)return 17; if(y<2044)return 19; if(y<4096)return 21; if(y<8192)return 23; if(y<16384)return 25; return 27; }
static int jbits(int v){ if(v<512)return 10; if(v<1024)return 12; if(v<2048)return 14; if(v<4096)return 16; return 18; }

/* ---------- LZ77 ---------- */
typedef struct { int is_copy; int off; int len; int val; } Op;
#define MAXOPS 20000
static Op ops[MAXOPS];
static int nop;
static int head[65536];
static int prevpos[12000];

#ifndef MATCH_REWARD
#define MATCH_REWARD 5
#endif
#ifndef MINMATCH
#define MINMATCH 2
#endif
#ifndef MAXCAND
#define MAXCAND 64
#endif

static int hashkey(int i){
  if (i+1 >= ndata) return -1;
  if (i+2 < ndata) return ((data[i]<<16)|(data[i+1]<<8)|data[i+2]) & 0xFFFF;
  return ((data[i]<<16)|data[i+1]) & 0xFFFF;
}
static void lz77(void){
  int i, p, k, m, L, d, c, considered, maxlen, key;
  int bestcost, besttype, bestoff, bestlen;
  memset(head, -1, sizeof(head));
  nop = 0; i = 0;
  key = hashkey(i); if (key>=0){ prevpos[i]=head[key]; head[key]=i; }
  while (i < ndata){
    bestcost = 2 + litbits(data[i]);
    besttype = 0; bestoff = 0; bestlen = 1;
    key = hashkey(i);
    if (key >= 0){
      p = head[key]; considered = 0;
      maxlen = ndata - i; if (maxlen > 9999) maxlen = 9999;
      while (p >= 0 && considered < MAXCAND){
        d = i - p;
        if (d >= 1 && d <= 9999){
          m = 0;
          while (m < maxlen && data[p+m] == data[i+m]) m++;
          if (m >= MINMATCH){
            for (k = 0; k < 4; k++){
              if (k==0) L = m; else if (k==1) L = m-1; else if (k==2) L = m/2; else L = 2;
              if (L < MINMATCH || L > m) continue;
              c = 1 + offbits(d-1) + lenbits(L-1) - (L-2)*MATCH_REWARD;
              if (c < bestcost){ bestcost = c; besttype = 1; bestoff = d; bestlen = L; }
            }
          }
        }
        p = prevpos[p]; considered++;
      }
    }
    if (besttype == 1){ ops[nop].is_copy=1; ops[nop].off=bestoff; ops[nop].len=bestlen; i+=bestlen; }
    else { ops[nop].is_copy=0; ops[nop].val=data[i]; i+=1; }
    nop++;
    key = hashkey(i); if (key>=0){ prevpos[i]=head[key]; head[key]=i; }
  }
}

/* ---------- build bit stream ---------- */
#define MAXBITS 400000
static int *cctx;
static int *cbit;
static int N;
static int buildfail = 0;

static void putbit(int ctx, int b){
  if (N >= MAXBITS){ buildfail = 1; return; }
  cctx[N] = ctx; cbit[N] = b; N++;
}
static void emit_get_integer(int t, int c, int v){
  int ctx99 = c*99, k = 1, e, b, ctx, nd;
  long hi = (1L<<t) - 1, datav;
  while (v > hi){ k++; hi = (1L<<(t+k)) - (1L<<t) - 1; }
  for (e = 0; e < k-1; e++){ ctx = t + (e+1) + ctx99; putbit(ctx, 0); }
  ctx = t + k + ctx99; putbit(ctx, 1);
  nd = t + k - 1;
  datav = v - (1L<<t)*((1L<<(k-1)) - 1);
  for (b = 0; b < nd; b++){
    int bit = (int)((datav >> (nd-1-b)) & 1);
    putbit(ctx99, bit);
  }
}
static void build_bits(void){
  int i;
  N = 0; buildfail = 0;
  cctx = (int*)malloc(MAXBITS*sizeof(int));
  cbit = (int*)malloc(MAXBITS*sizeof(int));
  emit_get_integer(9, 0, nop);
  for (i = 0; i < nop; i++){
    if (ops[i].is_copy){
      putbit(1, 1);
      emit_get_integer(5, 2, ops[i].off-1);
      emit_get_integer(2, 3, ops[i].len-1);
    } else {
      putbit(1, 0);
      putbit(8, 0);
      emit_get_integer(4, 9, ops[i].val);
    }
    if (buildfail) return;
  }
}

/* ---------- precompute decoder evolution ---------- */
static int *pc0, *pc1, *isref, *runend, *nextref;
static long *cW, *cS;
static double *La, *Lw;

static void precompute(void){
  static int tc0[4096], tc1[4096];
  long W = 1;
  int i, j;
  pc0 = malloc(N*sizeof(int)); pc1 = malloc(N*sizeof(int));
  isref = malloc(N*sizeof(int)); cW = malloc(N*sizeof(long)); cS = malloc(N*sizeof(long));
  runend = malloc(N*sizeof(int)); nextref = malloc(N*sizeof(int));
  La = malloc(N*sizeof(double)); Lw = malloc(N*sizeof(double));
  memset(tc0,0,sizeof(tc0)); memset(tc1,0,sizeof(tc1));
  for (i=0;i<N;i++){
    if (W < 255){ isref[i]=1; W *= 255; } else isref[i]=0;
    cW[i] = W;
    pc0[i] = tc0[cctx[i]]; pc1[i] = tc1[cctx[i]];
    cS[i] = W * (pc0[i]+1) / (pc0[i]+pc1[i]+2);
    if (cbit[i]) W = W - cS[i]; else W = cS[i];
    if (cbit[i]) tc1[cctx[i]]++; else tc0[cctx[i]]++;
  }
  i = 0;
  memset(nextref, -1, N*sizeof(int));
  while (i < N){
    j = i+1;
    while (j < N && !isref[j]) j++;
    runend[i] = j-1;
    nextref[i] = (j < N) ? j : -1;
    i = j;
  }
  for (i=0;i<N;i++){
    if (!isref[i]) continue;
    double a = 0.0, w = (double)cW[i];
    int k;
    for (k=i;k<=runend[i];k++){
      double ratio = (double)(pc0[k]+1)/(double)(pc0[k]+pc1[k]+2);
      double S = w * ratio;
      if (cbit[k]){ a += S; w -= S; } else { w = S; }
    }
    La[i] = a; Lw[i] = w;
  }
}

/* ---------- backtracking encoder with 2-level lookahead ---------- */
typedef struct {
  long i, frac, outlen, dlo, dhi;
  int n, idx;
  int cand[256];
  long qual[256];
} Ckpt;
static Ckpt stack[16384];
static int sp;
static unsigned char outbytes[32768];
static int outlen;
static long efrac;
static long nback, nref;

/* quality of candidate d: how well the resulting f_end positions the NEXT run */
static long cand_quality(Ckpt *cp, int d){
  long f = 255*cp->frac + d;
  long fend = (long)(f - La[cp->i] + 0.5);
  int nr = nextref[cp->i];
  if (nr < 0) return 0;
  {
    double nlo = 255.0*(double)fend;
    double nhi = 255.0*(double)fend + 254.0;
    double tlo = La[nr], thi = La[nr] + Lw[nr];
    double lo = nlo > tlo ? nlo : tlo;
    double hi = nhi < thi ? nhi : thi;
    double overlap = hi - lo;
    if (overlap > 0) return (long)(overlap * 100000.0);
    double dist = (nhi < tlo) ? (tlo - nhi) : (nlo - thi);
    return -(1000000000L + (long)(dist * 1000.0));
  }
}

static void build_cands(Ckpt *cp){
  long d; int x, y, bd;
  double mid = (cp->dlo + cp->dhi) * 0.5;
  cp->n = 0;
  for (d = cp->dlo; d <= cp->dhi; d++){
    cp->cand[cp->n] = (int)d;
    cp->qual[cp->n] = cand_quality(cp, (int)d);
    cp->n++;
  }
  for (x=0;x<cp->n;x++){
    bd = x;
    for (y=x+1;y<cp->n;y++){
      int better;
      if (cp->qual[y] != cp->qual[bd]) better = cp->qual[y] > cp->qual[bd];
      else better = fabs((double)cp->cand[y]-mid) < fabs((double)cp->cand[bd]-mid);
      if (better) bd = y;
    }
    if (bd != x){
      int tc = cp->cand[x]; long tq = cp->qual[x];
      cp->cand[x]=cp->cand[bd]; cp->qual[x]=cp->qual[bd];
      cp->cand[bd]=tc; cp->qual[bd]=tq;
    }
  }
  cp->idx = 0;
}

static int encode(void){
  long i = 0;
  efrac = 0; outlen = 0; sp = 0; nback = nref = 0;
  for (;;){
    while (i < N){
      if (isref[i]){
        Ckpt *cp = &stack[sp];
        long f255 = 255*efrac;
        long lo_f, hi_f, lo, hi;
        long dlo, dhi;
        int d;
        lo_f = (long)(La[i] + 1e-6);
        hi_f = (long)(La[i] + Lw[i] - 1e-6);
        lo = lo_f - f255; hi = hi_f - f255;
        dlo = lo; if (dlo < 0) dlo = 0;
        dhi = hi; if (dhi > 254) dhi = 254;
        if (dlo > dhi) goto fail;
        cp->i = i; cp->frac = efrac; cp->outlen = outlen; cp->dlo = dlo; cp->dhi = dhi;
        build_cands(cp);
        d = cp->cand[cp->idx++];
        efrac = 255*efrac + d;
        outbytes[outlen++] = (unsigned char)(d+1);
        efrac -= cS[i] * cbit[i];
        sp++; i++; nref++;
      } else {
        int actual = (efrac >= cS[i]) ? 1 : 0;
        if (actual != cbit[i]) goto fail;
        efrac -= cS[i] * cbit[i];
        i++;
      }
    }
    fprintf(stderr, "encode: refills=%ld backtracks=%ld\n", nref, nback);
    return 0;
fail:
    for (;;){
      Ckpt *cp;
      int d;
      if (sp == 0) return -1;
      cp = &stack[sp-1];
      if (cp->idx < cp->n){
        d = cp->cand[cp->idx++];
        nback++;
        efrac = cp->frac; outlen = cp->outlen; i = cp->i;
        efrac = 255*efrac + d;
        outbytes[outlen++] = (unsigned char)(d+1);
        efrac -= cS[i] * cbit[i];
        i++;
        break;
      }
      sp--;
    }
  }
}

/* ---------- self-check: faithful mirror of decomp.c ---------- */
static int dgc(const unsigned char *buf, int len, int *pos){
  if (*pos >= len) return -1;
  return (int)buf[(*pos)++];
}
static long drange; static int dfraction; static int dcc[1000000];
static int dget_bit(const unsigned char *buf, int len, int *pos, int ctx){
  if (drange < 255){
    drange *= 255;
    dfraction *= 255;
    dfraction += dgc(buf,len,pos)-1;
  }
  int *counts = dcc + ctx*2;
  int split = drange * -~*counts / (*counts + counts[1] + 2);
  int the_bit = dfraction >= split;
  dfraction -= split*the_bit;
  drange = the_bit ? drange-split : split;
  counts[the_bit]++;
  return the_bit;
}
static int dget_integer(const unsigned char *buf, int len, int *pos, int tmp, int ctx){
  int subtract_it = 1<<tmp, result_ans = 1, i;
  ctx*=99;
  while (!dget_bit(buf,len,pos,++tmp+ctx));
  tmp--;
  for (i=0;i<tmp;i++) result_ans = result_ans*2 | dget_bit(buf,len,pos,ctx);
  return result_ans - subtract_it;
}
static int lz77_verify(void){
  static unsigned char buf[10000];
  int Q = 0, i, k;
  for (i=0;i<nop;i++){
    if (ops[i].is_copy){
      int z = Q - ops[i].off;
      for (k=0;k<ops[i].len;k++) buf[Q+k] = buf[z+k];
      Q += ops[i].len;
    } else {
      buf[Q++] = (unsigned char)ops[i].val;
    }
  }
  if (Q != ndata){ fprintf(stderr,"lz77_verify: Q=%d ndata=%d\n", Q, ndata); return 0; }
  for (i=0;i<ndata;i++){
    if (buf[i] != data[i]){ fprintf(stderr,"lz77_verify: mismatch at %d\n", i); return 0; }
  }
  return 1;
}
static int selfcheck(void){
  static char buf[10000];
  char *Q = buf, *z;
  int j, tmp, pos = 0, i;
  drange = 1; dfraction = 0; memset(dcc,0,sizeof(dcc));
  j = dget_integer(outbytes, outlen, &pos, 9, 0);
  while (j--){
    if (dget_bit(outbytes,outlen,&pos,1)){
      z = Q - dget_integer(outbytes,outlen,&pos,5,2) - 1;
      tmp = dget_integer(outbytes,outlen,&pos,2,3) + 1;
      for (i=0;i<tmp;i++) *Q++ = *z++;
    } else {
      *Q++ = (1-2*dget_bit(outbytes,outlen,&pos,8)) * dget_integer(outbytes,outlen,&pos,4,9);
    }
  }
  {
    int outn = (int)(Q - buf);
    if (outn != ndata){ fprintf(stderr,"selfcheck: len %d != %d\n", outn, ndata); return 0; }
    if (memcmp(buf, data, ndata) != 0){ fprintf(stderr,"selfcheck: mismatch\n"); return 0; }
  }
  return 1;
}

int main(void){
  FILE *f;
  int i;
  long rawbits = 0;
