/* ---------- build bit stream ---------- */
#define MAXBITS 400000
static int *cctx;
static int *cbit;
static int N;
static int buildfail = 0;

static void putbit(int ctx, int b){
  if (N >= MAXBITS){ buildfail = 1; return; }
  cctx[N] = ctx; cbit[N] = b; N++;
}
static void emit_get_integer(int t, int c, int v){
  int ctx99 = c*99, k = 1, e, b, ctx, nd;
  long hi = (1L<<t) - 1, datav;
  while (v > hi){ k++; hi = (1L<<(t+k)) - (1L<<t) - 1; }
  for (e = 0; e < k-1; e++){ ctx = t + (e+1) + ctx99; putbit(ctx, 0); }
  ctx = t + k + ctx99; putbit(ctx, 1);
  nd = t + k - 1;
  datav = v - (1L<<t)*((1L<<(k-1)) - 1);
  for (b = 0; b < nd; b++){
    int bit = (int)((datav >> (nd-1-b)) & 1);
    putbit(ctx99, bit);
  }
}
static void build_bits(void){
  int i;
  N = 0; buildfail = 0;
  cctx = (int*)malloc(MAXBITS*sizeof(int));
  cbit = (int*)malloc(MAXBITS*sizeof(int));
  emit_get_integer(9, 0, nop);
  for (i = 0; i < nop; i++){
    if (ops[i].is_copy){
      putbit(1, 1);
      emit_get_integer(5, 2, ops[i].off-1);
      emit_get_integer(2, 3, ops[i].len-1);
    } else {
      putbit(1, 0);
      putbit(8, 0);
      emit_get_integer(4, 9, ops[i].val);
    }
    if (buildfail) return;
  }
}

/* ---------- precompute decoder evolution (exact) ---------- */
static int *pc0, *pc1, *isref, *runend, *nextref;
static long *cW, *cS;
static long *LA, *LW;   /* exact valid interval [LA, LA+LW) per run, post-refill units */

static void precompute(void){
  static int tc0[4096], tc1[4096];
  long W = 1;
  int i, j;
  pc0 = malloc(N*sizeof(int)); pc1 = malloc(N*sizeof(int));
  isref = malloc(N*sizeof(int)); cW = malloc(N*sizeof(long)); cS = malloc(N*sizeof(long));
  runend = malloc(N*sizeof(int)); nextref = malloc(N*sizeof(int));
  LA = malloc(N*sizeof(long)); LW = malloc(N*sizeof(long));
  memset(tc0,0,sizeof(tc0)); memset(tc1,0,sizeof(tc1));
  for (i=0;i<N;i++){
    if (W < 255){ isref[i]=1; W *= 255; } else isref[i]=0;
    cW[i] = W;
    pc0[i] = tc0[cctx[i]]; pc1[i] = tc1[cctx[i]];
    cS[i] = W * (pc0[i]+1) / (pc0[i]+pc1[i]+2);
    if (cbit[i]) W = W - cS[i]; else W = cS[i];
    if (cbit[i]) tc1[cctx[i]]++; else tc0[cctx[i]]++;
  }
  i = 0;
  memset(nextref, -1, N*sizeof(int));
  while (i < N){
    j = i+1;
    while (j < N && !isref[j]) j++;
    runend[i] = j-1;
    nextref[i] = (j < N) ? j : -1;
    i = j;
  }
  for (i=0;i<N;i++){
    if (!isref[i]) continue;
    long a = 0, w = cW[i];
    int k;
    for (k=i;k<=runend[i];k++){
      long S = w * (pc0[k]+1) / (pc0[k]+pc1[k]+2);
      if (cbit[k]){ a += S; w -= S; } else { w = S; }
    }
    LA[i] = a; LW[i] = w;
  }
}

/* ---------- backtracking encoder with 2-level lookahead ---------- */
typedef struct {
  long i, frac, outlen, dlo, dhi;
  int n, idx;
  int cand[256];
  long qual[256];
} Ckpt;
static Ckpt stack[16384];
static int sp;
static unsigned char outbytes[32768];
static int outlen;
static long efrac;
static long nback, nref;

/* quality of candidate d: how well the resulting f_end positions the NEXT run */
static long cand_quality(Ckpt *cp, int d){
  long f = 255*cp->frac + d;
  long fend = f - LA[cp->i];
  int nr = nextref[cp->i];
  if (nr < 0) return 0;
  {
    long nlo = 255*fend, nhi = 255*fend + 254;
    long tlo = LA[nr], thi = LA[nr] + LW[nr];
    long lo = nlo > tlo ? nlo : tlo;
    long hi = nhi < thi ? nhi : thi;
    if (hi >= lo) return (hi - lo) * 1000000L;
    return -(10000000000L + (nhi < tlo ? (tlo - nhi) : (nlo - thi)));
  }
}

static void build_cands(Ckpt *cp){
  long d; int x, y, bd;
  double mid = (cp->dlo + cp->dhi) * 0.5;
  cp->n = 0;
  for (d = cp->dlo; d <= cp->dhi; d++){
    cp->cand[cp->n] = (int)d;
    cp->qual[cp->n] = cand_quality(cp, (int)d);
    cp->n++;
  }
  for (x=0;x<cp->n;x++){
    bd = x;
    for (y=x+1;y<cp->n;y++){
      int better;
      if (cp->qual[y] != cp->qual[bd]) better = cp->qual[y] > cp->qual[bd];
      else better = fabs((double)cp->cand[y]-mid) < fabs((double)cp->cand[bd]-mid);
      if (better) bd = y;
    }
    if (bd != x){
      int tc = cp->cand[x]; long tq = cp->qual[x];
      cp->cand[x]=cp->cand[bd]; cp->qual[x]=cp->qual[bd];
      cp->cand[bd]=tc; cp->qual[bd]=tq;
    }
  }
  cp->idx = 0;
}

static int encode(void){
  long i = 0;
  efrac = 0; outlen = 0; sp = 0; nback = nref = 0;
  for (;;){
    while (i < N){
      if (isref[i]){
        Ckpt *cp = &stack[sp];
        long f255 = 255*efrac;
        long lo = LA[i] - f255;
        long hi = (LA[i] + LW[i] - 1) - f255;
        long dlo = lo; if (dlo < 0) dlo = 0;
        long dhi = hi; if (dhi > 254) dhi = 254;
        int d;
        if (dlo > dhi) goto fail;
        cp->i = i; cp->frac = efrac; cp->outlen = outlen; cp->dlo = dlo; cp->dhi = dhi;
        build_cands(cp);
        d = cp->cand[cp->idx++];
        efrac = 255*efrac + d;
        outbytes[outlen++] = (unsigned char)(d+1);
        efrac -= cS[i] * cbit[i];
        sp++; i++; nref++;
      } else {
        int actual = (efrac >= cS[i]) ? 1 : 0;
        if (actual != cbit[i]) goto fail;
        efrac -= cS[i] * cbit[i];
        i++;
      }
    }
    fprintf(stderr, "encode: refills=%ld backtracks=%ld\n", nref, nback);
    return 0;
fail:
    for (;;){
      Ckpt *cp;
      int d;
      if (sp == 0) return -1;
      cp = &stack[sp-1];
      if (cp->idx < cp->n){
        d = cp->cand[cp->idx++];
        nback++;
        efrac = cp->frac; outlen = cp->outlen; i = cp->i;
        efrac = 255*efrac + d;
        outbytes[outlen++] = (unsigned char)(d+1);
        efrac -= cS[i] * cbit[i];
        i++;
        break;
      }
      sp--;
    }
  }
}

/* ---------- self-check: faithful mirror of decomp.c ---------- */
static int dgc(const unsigned char *buf, int len, int *pos){
  if (*pos >= len) return -1;
  return (int)buf[(*pos)++];
}
static long drange; static int dfraction; static int dcc[1000000];
static int dget_bit(const unsigned char *buf, int len, int *pos, int ctx){
  if (drange < 255){
    drange *= 255;
    dfraction *= 255;
    dfraction += dgc(buf,len,pos)-1;
  }
  int *counts = dcc + ctx*2;
  int split = drange * -~*counts / (*counts + counts[1] + 2);
  int the_bit = dfraction >= split;
  dfraction -= split*the_bit;
  drange = the_bit ? drange-split : split;
  counts[the_bit]++;
  return the_bit;
}
static int dget_integer(const unsigned char *buf, int len, int *pos, int tmp, int ctx){
  int subtract_it = 1<<tmp, result_ans = 1, i;
  ctx*=99;
  while (!dget_bit(buf,len,pos,++tmp+ctx));
  tmp--;
  for (i=0;i<tmp;i++) result_ans = result_ans*2 | dget_bit(buf,len,pos,ctx);
  return result_ans - subtract_it;
}
static int lz77_verify(void){
  static unsigned char buf[10000];
  int Q = 0, i, k;
  for (i=0;i<nop;i++){
    if (ops[i].is_copy){
      int z = Q - ops[i].off;
      for (k=0;k<ops[i].len;k++) buf[Q+k] = buf[z+k];
      Q += ops[i].len;
    } else {
      buf[Q++] = (unsigned char)ops[i].val;
    }
  }
  if (Q != ndata){ fprintf(stderr,"lz77_verify: Q=%d ndata=%d\n", Q, ndata); return 0; }
  for (i=0;i<ndata;i++){
    if (buf[i] != data[i]){ fprintf(stderr,"lz77_verify: mismatch at %d\n", i); return 0; }
  }
  return 1;
}
static int selfcheck(void){
  static char buf[10000];
  char *Q = buf, *z;
  int j, tmp, pos = 0, i;
  drange = 1; dfraction = 0; memset(dcc,0,sizeof(dcc));
  j = dget_integer(outbytes, outlen, &pos, 9, 0);
  while (j--){
    if (dget_bit(outbytes,outlen,&pos,1)){
      z = Q - dget_integer(outbytes,outlen,&pos,5,2) - 1;
      tmp = dget_integer(outbytes,outlen,&pos,2,3) + 1;
      for (i=0;i<tmp;i++) *Q++ = *z++;
    } else {
      *Q++ = (1-2*dget_bit(outbytes,outlen,&pos,8)) * dget_integer(outbytes,outlen,&pos,4,9);
    }
  }
  {
    int outn = (int)(Q - buf);
    if (outn != ndata){ fprintf(stderr,"selfcheck: len %d != %d\n", outn, ndata); return 0; }
    if (memcmp(buf, data, ndata) != 0){ fprintf(stderr,"selfcheck: mismatch\n"); return 0; }
  }
  return 1;
}

int main(void){
  FILE *f;
  int i;
  long rawbits = 0;
  f = fopen("/app/data.txt","rb");
  if (!f){ perror("open"); return 1; }
  fseek(f,0,SEEK_END); ndata = (int)ftell(f); fseek(f,0,SEEK_SET);
  data = (unsigned char*)malloc(ndata+2);
  if (fread(data,1,ndata,f) != (size_t)ndata){ fprintf(stderr,"read fail\n"); return 1; }
  fclose(f); data[ndata]=0; data[ndata+1]=0;

  lz77();
  if (!lz77_verify()){ fprintf(stderr,"LZ77 VERIFY FAILED\n"); return 4; }
  rawbits = jbits(nop);
  for (i=0;i<nop;i++){
    if (ops[i].is_copy) rawbits += 1 + offbits(ops[i].off-1) + lenbits(ops[i].len-1);
    else rawbits += 2 + litbits(ops[i].val);
  }
  fprintf(stderr,"ndata=%d ops=%d rawbits=%ld (~%.1f bytes raw)\n", ndata, nop, rawbits, rawbits/8.0);

  build_bits();
  if (buildfail){ fprintf(stderr,"bitstream too long\n"); return 1; }
  precompute();
  if (encode() != 0){ fprintf(stderr,"ENCODE FAIL: no valid digit assignment found\n"); return 2; }
  fprintf(stderr,"encoded bytes=%d\n", outlen);

  if (!selfcheck()){ fprintf(stderr,"SELF-CHECK FAILED\n"); return 3; }
  fprintf(stderr,"self-check OK\n");

  f = fopen("/app/data.comp","wb");
  fwrite(outbytes,1,outlen,f); fclose(f);
  fprintf(stderr,"wrote /app/data.comp (%d bytes)\n", outlen);
  return 0;
}

