static void lz77(void){
  int i, p, k, m, L, d, c, considered, maxlen, key;
  int bestcost, besttype, bestoff, bestlen;
  memset(head, -1, sizeof(head));
  nop = 0; i = 0;
  key = hashkey(i); if (key>=0){ prevpos[i]=head[key]; head[key]=i; }
  while (i < ndata){
    bestcost = 2 + litbits(data[i]);
    besttype = 0; bestoff = 0; bestlen = 1;
    key = hashkey(i);
