  if (i+1 >= ndata) return -1;
  if (i+2 < ndata) return ((data[i]<<16)|(data[i+1]<<8)|data[i+2]) & 0xFFFF;
  return ((data[i]<<16)|data[i+1]) & 0xFFFF;
}
