  memset(head, -1, sizeof(head));
  nop = 0; i = 0;
  key = hashkey(i); if (key>=0){ prevpos[i]=head[key]; head[key]=i; }
  while (i < ndata){
    bestcost = 2 + litbits(data[i]);
    besttype = 0; bestoff = 0; bestlen = 1;
    key = hashkey(i);
    if (key >= 0){
      p = head[key]; considered = 0;
      maxlen = ndata - i; if (maxlen > 9999) maxlen = 9999;
      while (p >= 0 && considered < MAXCAND){
        d = i - p;
        if (d >= 1 && d <= 9999){
          m = 0;
          while (m < maxlen && data[p+m] == data[i+m]) m++;
          if (m >= MINMATCH){
            for (k = 0; k < 4; k++){
              if (k==0) L = m; else if (k==1) L = m-1; else if (k==2) L = m/2; else L = 2;
              if (L < MINMATCH || L > m) continue;
              c = 1 + offbits(d-1) + lenbits(L-1) - (L-2)*MATCH_REWARD;
              if (c < bestcost){ bestcost = c; besttype = 1; bestoff = d; bestlen = L; }
            }
          }
        }
        p = prevpos[p]; considered++;
      }
    }
    if (besttype == 1){ ops[nop].is_copy=1; ops[nop].off=bestoff; ops[nop].len=bestlen; i+=bestlen; }
    else { ops[nop].is_copy=0; ops[nop].val=data[i]; i+=1; }
