/* Encoder for /app/decomp.c  ->  produces /app/data.comp
 *
 * decomp.c: adaptive arithmetic (range, radix 255) + LZ77 decoder.
 *   j = get_integer(9,0); then j ops:
 *     bit1==1: off=get_integer(5,2), len=get_integer(2,3)+1, copy
 *     bit1==0: sign=get_bit(8), val=get_integer(4,9), byte=(1-2*sign)*val
 *   get_integer(t,c): ctx99=c*99; escapes get_bit(t+k+ctx99) until 1 (k>=1),
 *     then (t+k-1) data bits get_bit(ctx99); value=2^(t+k-1)+data-2^t.
 *   get_bit: if(range<255){range*=255;fraction*=255;fraction+=byte-1;}
 *     split=range*(c0+1)/(c0+c1+2); b=fraction>=split;
 *     fraction-=split*b; range=b?range-split:split; c[b]++;
 *
 * Strategy:
 *  - LZ77 ops chosen by a DP over positions that minimizes total raw-bit cost.
 *  - The raw bit stream is then adaptively range-coded. The per-context counts
 *    and the range evolution are precomputed EXACTLY (integer). Only the
 *    radix-255 digits at refill points are free. For each run we compute its
 *    exact valid interval [LA, LA+LW) for the post-refill fraction; a digit d
 *    is feasible iff 255*f + d falls in it. Candidates are ordered by how well
 *    they position the NEXT run (2-level lookahead) and DFS-backtracked.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static unsigned char *data;
static int ndata;

/* ---------- raw-bit cost helpers ----------
 * For get_integer(t,c): level K (K escapes) spans
 *   [ 2^t*(2^{K-1}-1) , 2^(t+K) - 2^t - 1 ]  and costs 2K+t-1 bits.          */
static int litbits(int v){ if(v<16)return 5; if(v<48)return 7; if(v<112)return 9; if(v<240)return 11; return 13; }
static int offbits(int x){ if(x<32)return 6; if(x<96)return 8; if(x<192)return 10; if(x<384)return 12; if(x<768)return 14; if(x<1536)return 16; if(x<3072)return 18; if(x<6144)return 20; if(x<12288)return 22; return 24; }
static int lenbits(int y){ if(y<6)return 3; if(y<12)return 5; if(y<28)return 7; if(y<60)return 9; if(y<124)return 11; if(y<252)return 13; if(y<508)return 15; if(y<1020)return 17; if(y<2044)return 19; if(y<4096)return 21; if(y<8192)return 23; if(y<16384)return 25; return 27; }
static int jbits(int v){ if(v<512)return 10; if(v<1024)return 12; if(v<2048)return 14; if(v<4096)return 16; return 18; }

/* ---------- LZ77 via DP over positions (minimize total raw-bit cost) ---------- */
typedef struct { int is_copy; int off; int len; int val; } Op;
#define MAXOPS 20000
static Op ops[MAXOPS];
static int nop;
static int head[65536];
static int prevpos[12000];

#ifndef MINMATCH
#define MINMATCH 2
#endif
#ifndef MAXCAND
#define MAXCAND 128
#endif
#define INFCOST 100000000

static int dp_cost[10005];
static int dp_type[10005];   /* 0=literal, 1=match */
static int dp_off[10005];
static int dp_len[10005];

static int hashkey(int i){
  if (i+1 >= ndata) return -1;
  if (i+2 < ndata) return ((data[i]<<16)|(data[i+1]<<8)|data[i+2]) & 0xFFFF;
  return ((data[i]<<16)|data[i+1]) & 0xFFFF;
}
static int matchcost(int d, int L){ return 1 + offbits(d-1) + lenbits(L-1); }
static int litcost(int v){ return 2 + litbits(v); }

static void add_hash(int pos){
  int key = hashkey(pos);
  if (key >= 0){ prevpos[pos] = head[key]; head[key] = pos; }
}
static void lz77(void){
  int i, p, m, d, key, considered, maxlen, L, c, x;
  memset(head, -1, sizeof(head));
  for (i = 0; i <= ndata; i++) dp_cost[i] = INFCOST;
  dp_cost[0] = 0;
  add_hash(0);
  for (i = 0; i < ndata; i++){
    if (dp_cost[i] == INFCOST){ add_hash(i); continue; }
    /* literal */
    c = dp_cost[i] + litcost(data[i]);
    if (c < dp_cost[i+1]){
      dp_cost[i+1] = c; dp_type[i+1] = 0; dp_off[i+1] = 0; dp_len[i+1] = 1;
    }
